var RenovationShopping=(()=>{
'use strict';
const $=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=n=>new Intl.NumberFormat('de-DE',{style:'currency',currency:'EUR'}).format(n);
let onChoose,items=[],busy=false,epoch=0;
async function call(path,body){let token;try{token=await FloorplanSession.access()}catch(e){if(e.code==='sign_in'){const err=Error('Bitte zuerst in ImmoBrain anmelden.');err.code='sign_in';throw err}throw e}const send=t=>fetch(path,{method:body?'POST':'GET',headers:{Authorization:'Bearer '+t,...(body?{'Content-Type':'application/json'}:{})},...(body?{body:JSON.stringify(body)}:{}),signal:AbortSignal.timeout(135000)});let r=await send(token);if(r.status===401){try{token=await FloorplanSession.access(true)}catch{const e=Error('Bitte erneut in ImmoBrain anmelden.');e.code='sign_in';throw e}r=await send(token)}const data=await r.json().catch(()=>({}));if(!r.ok){const e=Error(data.error||'Produktsuche fehlgeschlagen. Bitte später erneut versuchen.');e.code=data.code;throw e}return data}
function errorText(e){return e.name==='TimeoutError'?'Die Antwort der Produktsuche dauert zu lange. Bitte später erneut prüfen. Kein automatischer Wiederholungsversuch.':e.message+(e.code&&e.code!=='sign_in'?' [Fehlercode: '+e.code+']':'')}
function feedback(message,signIn=false){$('shopping-feedback').textContent=message;$('shopping-sign-in').hidden=!signIn}
function quota(data){if(!data.quota)return;$('shopping-quota').textContent=`SerpApi: ${data.quota.used} Abfragen im aktuellen Abrechnungsmonat · ${data.quota.remaining} bis zum App-Limit von 250 verfügbar${data.quotaBeforeSearch?' (Stand vor dieser Suche)':''}.`}
function render(data){items=Array.isArray(data.products)?data.products:[];quota(data);const stamp=new Date(data.checkedAt).toLocaleString('de-DE');$('shopping-results').innerHTML=items.map((p,i)=>`<article class="shopping-result"><div class="shopping-result-head"><span class="shopping-number">${i+1}</span><div><h3><a href="${esc(RenovationOffers.url(p.url))}" target="_blank" rel="noopener noreferrer">${esc(p.title)} ↗</a></h3><small>${esc(p.supplier)}</small></div><strong>${money(p.price)}</strong></div><div class="shopping-tags">${i===0?'<span>Niedrigster angezeigter Produktpreis</span>':''}${p.discount>0?`<span>${p.discount} % unter Vergleichspreis der Quelle (${money(p.oldPrice)})</span>`:''}</div><p>${p.shipping===null?'Versandkosten nicht bestätigt':p.shipping===0?'Versand laut Quelle kostenlos':'Versand: '+money(p.shipping)}${p.total!==null?' · Gesamt: '+money(p.total):''}</p>${p.delivery?`<small>${esc(p.delivery)}</small>`:''}${p.rating!==null?`<p>★ ${p.rating.toLocaleString('de-DE')} / 5${p.reviews!==null?' · '+p.reviews+' Bewertungen':''}</p>`:''}<div class="card-actions"><button type="button" class="btn" data-shopping-use="${i}">Preis &amp; Produkt prüfen</button><a href="${esc(RenovationOffers.url(p.url))}" target="_blank" rel="noopener noreferrer">Angebot öffnen ↗</a></div></article>`).join('');feedback(items.length?`${items.length} Vorschläge · Stand ${stamp}${data.cached?' · Wiederverwendetes Ergebnis':''}. Preise und Lieferumfang beim Anbieter prüfen.`:'Keine passenden Angebote mit bestätigtem Euro-Produktpreis gefunden. Bitte die Suche genauer formulieren.');}
function open(options={}){if(busy)return;epoch++;onChoose=options.onChoose;items=[];$('shopping-query').value=options.query||'';$('shopping-max').value='';$('shopping-results').innerHTML='';$('shopping-quota').textContent='';feedback('Produktbegriff eingeben und „Produkte finden“ anklicken.');$('shopping-dialog').showModal();$('shopping-query').focus()}
function init(){const d=document.createElement('dialog');d.id='shopping-dialog';d.innerHTML=`<div class="toolbar"><div><small class="tag">Online vergleichen</small><h2>Produkte &amp; Angebote finden</h2></div><button type="button" id="shopping-close">Schließen</button></div><form id="shopping-form"><div class="fields"><label>Was benötigst du?<input id="shopping-query" minlength="2" maxlength="200" required placeholder="z. B. Bosch Schlagbohrmaschine 750 Watt"></label><label>Maximaler Produktpreis (€) · optional<input id="shopping-max" type="number" min="0.01" max="100000000" step="0.01"></label></div><div class="card-actions"><button class="btn" type="submit" id="shopping-go">Produkte finden</button><button type="button" id="shopping-check">Verbindung prüfen</button></div></form><p class="muted">Die Suche übermittelt deinen Suchbegriff und Preisfilter an SerpApi / Google Shopping, keine Objekt- oder Adressdaten. Eine neue Suche kann eine API-Abfrage verbrauchen; es gibt keine automatische Hintergrundsuche. Ergebnisse können bis zu 15 Minuten wiederverwendet werden.</p><p id="shopping-quota" class="muted"></p><p id="shopping-feedback" role="status" aria-live="polite"></p><a id="shopping-sign-in" href="/besichtigungskalender.html#verbinden" hidden>In ImmoBrain anmelden →</a><div id="shopping-results"></div><p class="muted">Bis zu fünf Preisvorschläge aus einer begrenzten Ergebnisauswahl, kein vollständiger Marktvergleich oder Qualitätstest. Sortiert nach angezeigtem Produktpreis; unbekannter Versand wird nicht als kostenlos gewertet. Zubehör, Neuware, Lieferumfang und Packungsinhalt bitte prüfen. Anbieterlinks können zunächst zur Google-Produktübersicht führen.</p>`;document.body.appendChild(d);
$('shopping-close').onclick=()=>{epoch++;d.close()};d.addEventListener('cancel',()=>{epoch++});
const state=b=>{busy=b;$('shopping-go').disabled=b;$('shopping-check').disabled=b;$('shopping-go').textContent=b?'Wird gesucht …':'Produkte finden'};
$('shopping-form').onsubmit=async e=>{e.preventDefault();if(busy||!$('shopping-form').reportValidity())return;const query=$('shopping-query').value.trim(),maxPrice=$('shopping-max').value,version=epoch;state(true);$('shopping-results').innerHTML='';items=[];feedback('Angebote werden gesucht. Das kann einige Sekunden dauern.');try{const data=await call('/api/shopping/search',{query,maxPrice});if(version===epoch)render(data)}catch(e){if(version===epoch)feedback(e.code==='sign_in'?'Bitte in ImmoBrain anmelden und anschließend erneut suchen.':errorText(e),e.code==='sign_in')}finally{state(false)}};
$('shopping-check').onclick=async()=>{if(busy)return;const version=epoch;state(true);feedback('Verbindung und Kontingent werden geprüft …');try{const data=await call('/api/shopping/status');if(version===epoch){quota(data);feedback('SerpApi-Verbindung funktioniert. Du kannst Produkte suchen.')}}catch(e){if(version===epoch)feedback(e.code==='sign_in'?'Bitte zuerst in ImmoBrain anmelden.':errorText(e),e.code==='sign_in')}finally{state(false)}};
$('shopping-results').onclick=e=>{const b=e.target.closest('[data-shopping-use]');if(!b)return;const item=items[Number(b.dataset.shoppingUse)];if(!item||!onChoose)return;epoch++;d.close();onChoose(item)};
}
return {init,open};})();
